/**
 * Module types for static image imports resolved by Metro. Add
 * `"@effect/ui-native/assets"` to `compilerOptions.types`, or reference it
 * with `/// <reference types="@effect/ui-native/assets" />`.
 *
 * @stability experimental
 * @since 0.1.0
 */
declare module "*.avif" {
  const asset: number
  export default asset
}
declare module "*.bmp" {
  const asset: number
  export default asset
}
declare module "*.gif" {
  const asset: number
  export default asset
}
declare module "*.heic" {
  const asset: number
  export default asset
}
declare module "*.heif" {
  const asset: number
  export default asset
}
declare module "*.jpeg" {
  const asset: number
  export default asset
}
declare module "*.jpg" {
  const asset: number
  export default asset
}
declare module "*.png" {
  const asset: number
  export default asset
}
declare module "*.psd" {
  const asset: number
  export default asset
}
declare module "*.svg" {
  const asset: number
  export default asset
}
declare module "*.tif" {
  const asset: number
  export default asset
}
declare module "*.tiff" {
  const asset: number
  export default asset
}
declare module "*.webp" {
  const asset: number
  export default asset
}
